339	fn replay(gpa: Allocator, io: std.Io, target: Target, paths: []const []const u8) !void {
340	    var arena_state = std.heap.ArenaAllocator.init(gpa);
341	    defer arena_state.deinit();
342	    const a = arena_state.allocator();
343	    var files: std.ArrayList([]const u8) = .empty;
344	    for (paths) |p| try listInputs(a, io, p, &files);
345	    var ok: usize = 0;
346	    var errors: usize = 0;
347	    var skipped: usize = 0;
348	    explain = files.items.len == 1;
349	    for (files.items) |path| {
350	        const raw = std.Io.Dir.cwd().readFileAlloc(io, path, gpa, .limited(max_input_len)) catch |e| {
351	            std.debug.print("skip {s}: {s}\n", .{ path, @errorName(e) });
352	            skipped += 1;
353	            continue;
