4	/// Fuzz decisions read from the input. Exhausted input yields zeros, so a shorter
5	/// input is always a smaller case: truncating is our shrinker.
6	pub const Input = struct {
7	    bytes: []const u8,
8	    pos: usize = 0,
9	
10	    pub fn byte(in: *Input) u8 {
11	        if (in.pos >= in.bytes.len) return 0;
12	        defer in.pos += 1;
13	        return in.bytes[in.pos];
14	    }
15	    /// In [0, n); 0 when n == 0.
16	    pub fn below(in: *Input, n: usize) usize {
17	        if (n == 0) return 0;
18	        return (@as(usize, in.byte()) | @as(usize, in.byte()) << 8) % n;
19	    }
20	    /// Little-endian, zero-padded past the end.
21	    pub fn int(in: *Input, comptime T: type) T {
22	        var buf: [@sizeOf(T)]u8 = @splat(0);
23	        for (&buf) |*b| b.* = in.byte();
24	        return std.mem.readInt(T, &buf, .little);
25	    }
26	    pub fn rest(in: *Input) []const u8 {
27	        const r = in.bytes[@min(in.pos, in.bytes.len)..];
28	        in.pos = in.bytes.len;
29	        return r;
30	    }
31	};
32	
33	/// What one execution looked like; a new `sig` grows the run loop's corpus.
34	pub const Feedback = struct {
35	    err: ?anyerror = null,
36	    rows: u64 = 0,
37	    detail: u64 = 0, // target-specific bits (encodings seen, reader modes that succeeded, ...)
38	
39	    pub fn sig(f: Feedback) u64 {
40	        var h = std.hash.Wyhash.init(0);
41	        h.update(if (f.err) |e| @errorName(e) else "ok");
42	        h.update(std.mem.asBytes(&@min(f.rows, 8)));
43	        h.update(std.mem.asBytes(&f.detail));
44	        return h.final();
45	    }
46	};
